DROP INDEX IF EXISTS idx_pay_method_status;
CREATE INDEX idx_pay_method_status ON payments(payment_method, payment_status);
SELECT name, tbl_name FROM sqlite_master WHERE type = 'index' AND name = 'idx_pay_method_status';

DROP INDEX IF EXISTS idx_orders_cust_date;
CREATE INDEX idx_orders_cust_date ON orders(customer_id, order_date);
SELECT seqno, name AS column_name FROM pragma_index_info('idx_orders_cust_date') ORDER BY seqno;
